import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Queue;

class Node {
    public int val;
    public List<Node> neighbors;
    public Node() { val = 0; neighbors = new ArrayList<>(); }
    public Node(int val) { this.val = val; neighbors = new ArrayList<>(); }
    public Node(int val, List<Node> neighbors) { this.val = val; this.neighbors = neighbors; }
}

class Solution {
    public Node cloneGraph(Node node) {
        if (node == null) return null;
        Map<Node, Node> clones = new HashMap<>();
        Queue<Node> queue = new ArrayDeque<>();
        clones.put(node, new Node(node.val));
        queue.offer(node);
        while (!queue.isEmpty()) {
            Node original = queue.poll();
            Node copy = clones.get(original);
            for (Node neighbor : original.neighbors) {
                if (!clones.containsKey(neighbor)) {
                    clones.put(neighbor, new Node(neighbor.val));
                    queue.offer(neighbor);
                }
                copy.neighbors.add(clones.get(neighbor));
            }
        }
        return clones.get(node);
    }
}
